'use strict';

// Configuración editable del bot: pestaña BOT_CONFIG con las columnas clave | valor | descripcion.
// El dashboard la cambia por la API y el bot la lee en cada mensaje. Una clave vacía o ausente toma el valor
// por defecto. Sin dependencias: se usa en los nodos Code de n8n y en el simulador.

const CONFIG_POR_DEFECTO = {
  nombre_bot: 'Mermín',
  nombre_negocio: 'ITS WOOD',
  tono: 'cercano',
  emoji_bot: '🌳',
  url_web: '',
  codigo_descuento_web: 'WEB10',
  porcentaje_descuento_web: '10',
  // Vacío: se usa la plantilla del tono elegido (ver plantillaBienvenida).
  mensaje_bienvenida: '',
  drive_folder_id: '',
  sheet_fuente_id: '',
  ultima_sync: '',
  margen_por_defecto: '0.40',
  umbral_prioridad_alta: '70',
  umbral_prioridad_media: '40',
  // Topes con los que se normalizan valor, ganancia y cantidad en la prioridad (recortados a 1).
  tope_valor: '3000',
  tope_ganancia: '1200',
  tope_cantidad: '50',
  tfr_antes_minutos: '180',
  avisos_whatsapp: '',
  avisos_email: '',
  hora_resumen_diario: '19:00',
};

const DESCRIPCIONES_CONFIG = {
  nombre_bot: 'Nombre con el que se presenta el bot.',
  nombre_negocio: 'Nombre del negocio en los mensajes.',
  tono: 'cercano (tutea) o formal (trata de usted).',
  emoji_bot: 'Emoji que acompaña al nombre del bot.',
  url_web: 'Tienda web a la que se redirige en el primer mensaje. Vacío = sin enlace.',
  codigo_descuento_web: 'Código de descuento para comprar en la web.',
  porcentaje_descuento_web: 'Porcentaje del descuento web (solo el número).',
  mensaje_bienvenida: 'Plantilla del primer mensaje: {hola}, {nombre_bot}, {emoji_bot}, {nombre_negocio}, {porcentaje}, {codigo}, {url}. Vacío = plantilla del tono.',
  drive_folder_id: 'Carpeta de Drive con la hoja MERMIN_FUENTE. Se llena desde el dashboard.',
  sheet_fuente_id: 'Hoja fuente detectada por la sincronización.',
  ultima_sync: 'Fecha de la última sincronización correcta.',
  margen_por_defecto: 'Margen para productos sin costo (0.40 = 40 %).',
  umbral_prioridad_alta: 'Puntaje desde el que un lead es ALTA.',
  umbral_prioridad_media: 'Puntaje desde el que un lead es MEDIA.',
  tope_valor: 'Valor (S/) que cuenta como 100 % en la prioridad.',
  tope_ganancia: 'Ganancia (S/) que cuenta como 100 % en la prioridad.',
  tope_cantidad: 'Unidades que cuentan como 100 % en la prioridad.',
  tfr_antes_minutos: 'Tiempo de primera respuesta antes del bot, en minutos (línea base manual).',
  avisos_whatsapp: 'WhatsApp que recibe los avisos de leads ALTA (con código de país).',
  avisos_email: 'Correos que reciben los resúmenes, separados por coma.',
  hora_resumen_diario: 'Hora del resumen diario (HH:MM, hora de Lima).',
};

// Claves que el dashboard no edita con PUT /config: las escribe la sincronización o POST /config/drive.
const CLAVES_SOLO_LECTURA = ['sheet_fuente_id', 'ultima_sync', 'drive_folder_id'];

const PLANTILLAS_BIENVENIDA = {
  cercano: '{hola} Soy {nombre_bot} {emoji_bot}, el asistente de {nombre_negocio}. {web}\n¿Prefieres que te ayude por aquí? Cuéntame si es para tu *empresa* o para *ti*.',
  formal: '{hola} Soy {nombre_bot} {emoji_bot}, el asistente de {nombre_negocio}. {web}\n¿Prefiere que le ayude por aquí? Indíqueme si es para su *empresa* o para *usted*.',
};

function cfgTexto(v) { return v === undefined || v === null ? '' : String(v).trim(); }

// Filas de BOT_CONFIG -> objeto con todas las claves (las desconocidas también se conservan).
function leerConfig(filas) {
  const config = { ...CONFIG_POR_DEFECTO };
  for (const f of filas || []) {
    const clave = cfgTexto(f && f.clave);
    const valor = cfgTexto(f && f.valor);
    if (clave && valor !== '') config[clave] = valor;
  }
  config.tono = config.tono.toLowerCase() === 'formal' ? 'formal' : 'cercano';
  return config;
}

function numeroConfig(config, clave) {
  const n = Number(cfgTexto(config[clave]).replace(',', '.'));
  return Number.isFinite(n) ? n : Number(CONFIG_POR_DEFECTO[clave]);
}

// Reemplaza {clave} por su valor; las claves sin valor quedan vacías.
function render(plantilla, valores) {
  return cfgTexto(plantilla).replace(/\{(\w+)\}/g, (_, k) => cfgTexto((valores || {})[k]));
}

function slug(v) {
  return cfgTexto(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

// URL de la web con UTM: así se mide qué ventas web vinieron del bot.
function urlConUtm(config) {
  const url = cfgTexto(config.url_web);
  if (!url) return '';
  return `${url}${url.includes('?') ? '&' : '?'}utm_source=whatsapp&utm_campaign=${slug(config.nombre_bot) || 'bot'}`;
}

function valoresPlantilla(config, extra) {
  return {
    ...config,
    porcentaje: config.porcentaje_descuento_web,
    codigo: config.codigo_descuento_web,
    url: urlConUtm(config),
    ...(extra || {}),
  };
}

// Frase de la web con el descuento, o vacía si no hay URL.
function fraseWeb(config) {
  const url = urlConUtm(config);
  if (!url) return '';
  const compra = config.tono === 'formal' ? 'Compre' : 'Compra';
  const lleva = config.tono === 'formal' ? 'llévese' : 'llévate';
  const codigo = cfgTexto(config.codigo_descuento_web);
  const pct = cfgTexto(config.porcentaje_descuento_web);
  const descuento = pct && codigo ? ` y ${lleva} *${pct}% de descuento* con el código *${codigo}*` : '';
  return `*${compra} en nuestra web*${descuento} 👉 ${url}`;
}

function plantillaBienvenida(config) {
  return cfgTexto(config.mensaje_bienvenida) || PLANTILLAS_BIENVENIDA[config.tono] || PLANTILLAS_BIENVENIDA.cercano;
}

function mensajeBienvenida(config, nombre) {
  const formal = config.tono === 'formal';
  const hola = nombre ? `¡Hola de nuevo, ${nombre}!` : formal ? '¡Buen día!' : '¡Hola!';
  const texto = render(plantillaBienvenida(config), valoresPlantilla(config, { hola, web: fraseWeb(config) }));
  // Sin URL la frase de la web queda vacía: se limpian los espacios que deja.
  return texto.replace(/[ \t]+\n/g, '\n').replace(/[ \t]{2,}/g, ' ').trim();
}

// Cambios pedidos por el dashboard ({ clave: valor }) -> filas a guardar, o error.
function validarCambiosConfig(cambios) {
  if (!cambios || typeof cambios !== 'object' || Array.isArray(cambios)) return { ok: false, error: 'El cuerpo debe ser un objeto { clave: valor }.' };
  const filas = [];
  for (const [clave, bruto] of Object.entries(cambios)) {
    if (!(clave in CONFIG_POR_DEFECTO)) return { ok: false, error: `Clave desconocida: ${clave}.` };
    if (CLAVES_SOLO_LECTURA.includes(clave)) return { ok: false, error: `${clave} no se edita con PUT /config.` };
    const valor = cfgTexto(bruto);
    if (valor.length > 1000) return { ok: false, error: `${clave} admite hasta 1000 caracteres.` };
    if (clave === 'tono' && valor && !['cercano', 'formal'].includes(valor.toLowerCase())) return { ok: false, error: 'tono debe ser cercano o formal.' };
    if (clave === 'hora_resumen_diario' && valor && !/^([01]?\d|2[0-3]):[0-5]\d$/.test(valor)) return { ok: false, error: 'hora_resumen_diario debe ser HH:MM.' };
    if (clave === 'url_web' && valor && !/^https?:\/\/\S+$/.test(valor)) return { ok: false, error: 'url_web debe empezar por http:// o https://.' };
    const numericas = ['margen_por_defecto', 'umbral_prioridad_alta', 'umbral_prioridad_media', 'tope_valor', 'tope_ganancia', 'tope_cantidad', 'tfr_antes_minutos', 'porcentaje_descuento_web'];
    if (numericas.includes(clave) && valor && !(Number(valor.replace(',', '.')) >= 0)) return { ok: false, error: `${clave} debe ser un número.` };
    filas.push({ clave, valor, descripcion: DESCRIPCIONES_CONFIG[clave] || '' });
  }
  if (!filas.length) return { ok: false, error: 'No hay cambios.' };
  return { ok: true, filas };
}

// Filas iniciales de BOT_CONFIG (plantilla de la hoja).
function filasConfigIniciales() {
  return Object.keys(CONFIG_POR_DEFECTO).map(clave => ({ clave, valor: CONFIG_POR_DEFECTO[clave], descripcion: DESCRIPCIONES_CONFIG[clave] || '' }));
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    leerConfig, render, numeroConfig, urlConUtm, fraseWeb, mensajeBienvenida, valoresPlantilla, validarCambiosConfig,
    filasConfigIniciales, CONFIG_POR_DEFECTO, DESCRIPCIONES_CONFIG, CLAVES_SOLO_LECTURA, COLUMNAS_CONFIG: ['clave', 'valor', 'descripcion'],
  };
}

// ---- n8n ----
const config = leerConfig($input.all().map(i => i.json));
return [{ json: config.drive_folder_id
  ? { ok: true, folder_id: config.drive_folder_id }
  : { ok: false, error: 'Falta conectar la carpeta de Drive (POST /config/drive).' } }];

'use strict';

// Sincronización de la carpeta de Drive: el negocio deja ahí su hoja MERMIN_FUENTE (pestañas PRODUCTOS, CLIENTES y
// VENTAS) y el flujo [8] la copia a BOT_PRODUCTOS, BOT_CLIENTES_FUENTE y BOT_VENTAS. El bot y el dashboard leen la
// copia, nunca la fuente: si el negocio rompe su hoja, se registra el error y queda la última copia válida.
// Sin dependencias: se usa en los nodos Code de n8n y en el simulador.

const PREFIJO_FUENTE = 'MERMIN_FUENTE';
const MIME_SHEETS = 'application/vnd.google-apps.spreadsheet';
const COLUMNAS_FUENTE = {
  PRODUCTOS: ['sku', 'nombre', 'categoria', 'precio', 'costo', 'stock', 'activo'],
  CLIENTES: ['cliente_id', 'nombre', 'telefono', 'email', 'tipo', 'fecha_registro', 'acepta_marketing'],
  VENTAS: ['fecha', 'pedido_id', 'cliente_id', 'sku', 'cantidad', 'total', 'canal', 'codigo'],
};
const TIPOS_CLIENTE = ['EMPRESA', 'PERSONA'];
const CANALES_VENTA = ['WEB', 'WHATSAPP', 'TIENDA'];

function syncTexto(v) { return v === undefined || v === null ? '' : String(v).trim(); }
function syncClave(v) { return syncTexto(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, '_'); }
function syncNumero(v) {
  const s = syncTexto(v).replace(/^S\/\s*/i, '').replace(/\s/g, '');
  if (!s) return null;
  // "1,234.50" o "1234,50": la coma es decimal solo si no hay punto.
  const limpio = s.includes('.') ? s.replace(/,/g, '') : s.replace(',', '.');
  const n = Number(limpio);
  return Number.isFinite(n) ? n : null;
}

// Fecha de la hoja -> YYYY-MM-DD. Acepta 2026-10-17, 17/10/2026, 17/10/26, ISO con hora y el número de serie de Sheets.
function fechaFuente(v) {
  const s = syncTexto(v);
  if (!s) return '';
  let g;
  if ((g = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/))) return armarFecha(+g[1], +g[2], +g[3]);
  if ((g = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2}|\d{4})$/))) return armarFecha(g[3].length === 2 ? 2000 + +g[3] : +g[3], +g[2], +g[1]);
  if (/^\d{5}(\.\d+)?$/.test(s)) return new Date(Date.UTC(1899, 11, 30) + Math.floor(Number(s)) * 864e5).toISOString().slice(0, 10);
  return '';
}
function armarFecha(y, m, d) {
  const t = new Date(Date.UTC(y, m - 1, d));
  return t.getUTCFullYear() === y && t.getUTCMonth() === m - 1 && t.getUTCDate() === d ? t.toISOString().slice(0, 10) : '';
}

function telefonoFuente(v) {
  const d = syncTexto(v).replace(/\D/g, '');
  if (/^9\d{8}$/.test(d)) return `51${d}`;
  return d.length >= 10 ? d : '';
}
function siNo(v, porDefecto) {
  const s = syncClave(v);
  if (!s) return porDefecto;
  return ['si', 'sí', 's', 'yes', 'y', 'true', '1', 'x'].includes(s) ? 'SI' : 'NO';
}

// URL de la carpeta (o el id suelto) -> folderId.
function extraerFolderId(url) {
  const s = syncTexto(url);
  let g;
  if ((g = s.match(/\/folders\/([A-Za-z0-9_-]{10,})/))) return g[1];
  if ((g = s.match(/[?&]id=([A-Za-z0-9_-]{10,})/))) return g[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(s)) return s;
  return '';
}

// Archivos de la carpeta (búsqueda de Drive) -> la hoja fuente: la que empieza por MERMIN_FUENTE o la primera Sheet.
function elegirHojaFuente(archivos) {
  const hojas = (archivos || []).filter(a => a && syncTexto(a.id) && (!a.mimeType || a.mimeType === MIME_SHEETS));
  const porNombre = hojas.find(a => syncTexto(a.name).toUpperCase().startsWith(PREFIJO_FUENTE));
  const elegida = porNombre || hojas[0];
  return elegida ? { id: syncTexto(elegida.id), nombre: syncTexto(elegida.name) } : null;
}

// Filas leídas de una pestaña -> filas con claves normalizadas, sin filas vacías.
function filasLimpias(filas) {
  return (filas || [])
    .map(f => {
      const fila = {};
      for (const k of Object.keys(f || {})) if (k !== 'row_number') fila[syncClave(k)] = f[k];
      return fila;
    })
    .filter(f => Object.values(f).some(v => syncTexto(v) !== ''));
}

function columnasFaltantes(pestana, filas) {
  const vistas = new Set();
  for (const f of filas) for (const k of Object.keys(f)) vistas.add(k);
  return COLUMNAS_FUENTE[pestana].filter(c => !vistas.has(c));
}

function normalizarProductos(filas, avisos) {
  const vistos = new Set();
  const productos = [];
  for (const f of filas) {
    const sku = syncTexto(f.sku);
    if (!sku) { avisos.push(`PRODUCTOS: fila sin sku omitida (${syncTexto(f.nombre) || 'sin nombre'}).`); continue; }
    if (vistos.has(sku)) { avisos.push(`PRODUCTOS: sku ${sku} repetido; se usa la primera fila.`); continue; }
    vistos.add(sku);
    const precio = syncNumero(f.precio);
    if (precio === null) avisos.push(`PRODUCTOS: ${sku} sin precio.`);
    const costo = syncNumero(f.costo);
    const stock = syncNumero(f.stock);
    productos.push({
      sku, nombre: syncTexto(f.nombre), categoria: syncTexto(f.categoria),
      precio: precio === null ? '' : precio, costo: costo === null ? '' : costo,
      stock: stock === null ? '' : Math.floor(stock), activo: siNo(f.activo, 'SI'),
    });
  }
  return productos;
}

function normalizarClientes(filas, avisos) {
  const clientes = [];
  const vistos = new Set();
  for (const f of filas) {
    const id = syncTexto(f.cliente_id);
    if (!id) { avisos.push('CLIENTES: fila sin cliente_id omitida.'); continue; }
    if (vistos.has(id)) { avisos.push(`CLIENTES: cliente_id ${id} repetido; se usa la primera fila.`); continue; }
    vistos.add(id);
    const tipo = syncTexto(f.tipo).toUpperCase();
    if (tipo && !TIPOS_CLIENTE.includes(tipo)) avisos.push(`CLIENTES: ${id} tiene tipo "${tipo}"; se toma como PERSONA.`);
    clientes.push({
      cliente_id: id, nombre: syncTexto(f.nombre), telefono: telefonoFuente(f.telefono), email: syncTexto(f.email).toLowerCase(),
      tipo: tipo === 'EMPRESA' ? 'EMPRESA' : 'PERSONA', fecha_registro: fechaFuente(f.fecha_registro),
      acepta_marketing: siNo(f.acepta_marketing, 'NO'),
    });
  }
  return clientes;
}

function normalizarVentas(filas, productos, avisos) {
  const precios = Object.fromEntries(productos.map(p => [p.sku, p.precio]));
  const ventas = [];
  for (const f of filas) {
    const fecha = fechaFuente(f.fecha);
    const pedido = syncTexto(f.pedido_id);
    if (!fecha || !pedido) { avisos.push(`VENTAS: fila sin fecha válida o sin pedido_id omitida (${pedido || syncTexto(f.fecha) || 'vacía'}).`); continue; }
    const cantidad = syncNumero(f.cantidad);
    let total = syncNumero(f.total);
    const sku = syncTexto(f.sku);
    if (total === null && cantidad !== null && typeof precios[sku] === 'number') total = Math.round(precios[sku] * cantidad * 100) / 100;
    const canal = syncTexto(f.canal).toUpperCase();
    ventas.push({
      fecha, pedido_id: pedido, cliente_id: syncTexto(f.cliente_id), sku,
      cantidad: cantidad === null ? '' : cantidad, total: total === null ? '' : total,
      canal: CANALES_VENTA.includes(canal) ? canal : canal || 'TIENDA', codigo: syncTexto(f.codigo).toUpperCase(),
    });
  }
  return ventas;
}

// Lo leído de la hoja fuente -> qué escribir. Si falta una columna o no hay productos, no se escribe nada.
function prepararSync({ hoja, productos, clientes, ventas, ahora }) {
  const ahoraIso = ahora || new Date().toISOString();
  const errores = [];
  const avisos = [];
  if (!hoja) {
    return { ok: false, errores: [`No hay una hoja de cálculo en la carpeta. Sube la plantilla ${PREFIJO_FUENTE}.`], avisos, ahora: ahoraIso };
  }
  const leidas = { PRODUCTOS: filasLimpias(productos), CLIENTES: filasLimpias(clientes), VENTAS: filasLimpias(ventas) };
  for (const pestana of Object.keys(COLUMNAS_FUENTE)) {
    // Una pestaña vacía no deja ver sus cabeceras: solo se exige que PRODUCTOS tenga filas.
    if (!leidas[pestana].length) {
      if (pestana === 'PRODUCTOS') errores.push('La pestaña PRODUCTOS no tiene filas (o no existe).');
      continue;
    }
    const faltan = columnasFaltantes(pestana, leidas[pestana]);
    if (faltan.length) errores.push(`A la pestaña ${pestana} le faltan columnas: ${faltan.join(', ')}.`);
  }
  if (errores.length) return { ok: false, errores, avisos, hoja, ahora: ahoraIso };

  const prods = normalizarProductos(leidas.PRODUCTOS, avisos);
  const clis = normalizarClientes(leidas.CLIENTES, avisos);
  const vents = normalizarVentas(leidas.VENTAS, prods, avisos);
  const idsClientes = new Set(clis.map(c => c.cliente_id));
  const sinCliente = vents.filter(v => v.cliente_id && !idsClientes.has(v.cliente_id)).length;
  if (sinCliente) avisos.push(`VENTAS: ${sinCliente} fila(s) con cliente_id que no está en CLIENTES.`);
  return {
    ok: true,
    errores,
    avisos: avisos.slice(0, 50),
    hoja,
    ahora: ahoraIso,
    productos: prods,
    clientes: clis,
    ventas: vents,
    config: [
      { clave: 'sheet_fuente_id', valor: hoja.id, descripcion: 'Hoja fuente detectada por la sincronización.' },
      { clave: 'ultima_sync', valor: ahoraIso, descripcion: 'Fecha de la última sincronización correcta.' },
    ],
    resumen: `${prods.length} productos, ${clis.length} clientes y ${vents.length} líneas de venta desde "${hoja.nombre}".`,
  };
}

// Fila de BOT_ERRORES para una sincronización fallida.
function filaErrorSync(resultado) {
  return {
    fecha: resultado.ahora, flujo: 'Mermín - Sincronizar Drive', nodo: 'Validar fuente',
    mensaje: resultado.errores.join(' ').slice(0, 500), ejecucion_id: '', modo: 'sync',
  };
}

// POST /config/drive: lo que encontró la búsqueda en la carpeta -> respuesta y filas de BOT_CONFIG.
function conectarDrive({ url, archivos, correoServicio }) {
  const folderId = extraerFolderId(url);
  if (!folderId) return { ok: false, status: 400, error: 'No reconozco esa URL. Pega el enlace de la carpeta de Drive (…/drive/folders/<id>).' };
  const hoja = elegirHojaFuente(archivos);
  if (!hoja) {
    const correo = syncTexto(correoServicio);
    return {
      ok: false, status: 403, folder_id: folderId, correo_servicio: correo,
      error: `No veo ninguna hoja de cálculo en esa carpeta. Compártela${correo ? ` con ${correo}` : ' con la cuenta de servicio'} (como lector) y sube la plantilla ${PREFIJO_FUENTE}.`,
    };
  }
  return {
    ok: true, status: 200, folder_id: folderId, hoja,
    config: [
      { clave: 'drive_folder_id', valor: folderId, descripcion: 'Carpeta de Drive con la hoja MERMIN_FUENTE. Se llena desde el dashboard.' },
      { clave: 'sheet_fuente_id', valor: hoja.id, descripcion: 'Hoja fuente detectada por la sincronización.' },
    ],
  };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    extraerFolderId, elegirHojaFuente, prepararSync, filaErrorSync, conectarDrive, fechaFuente, telefonoFuente,
    COLUMNAS_FUENTE, PREFIJO_FUENTE, MIME_SHEETS,
  };
}

// ---- n8n ----
const archivos = $input.all().map(i => i.json).filter(a => a && a.id);
return [{ json: { hoja: elegirHojaFuente(archivos) } }];

'use strict';

// Sincronización de la carpeta de Drive: el negocio deja ahí su hoja MERMIN_FUENTE (pestañas PRODUCTOS, CLIENTES y
// VENTAS) y el flujo [8] la copia a BOT_PRODUCTOS, BOT_CLIENTES_FUENTE y BOT_VENTAS. El bot y el dashboard leen la
// copia, nunca la fuente: si el negocio rompe su hoja, se registra el error y queda la última copia válida.
// Sin dependencias: se usa en los nodos Code de n8n y en el simulador.

const PREFIJO_FUENTE = 'MERMIN_FUENTE';
const MIME_SHEETS = 'application/vnd.google-apps.spreadsheet';
const COLUMNAS_FUENTE = {
  PRODUCTOS: ['sku', 'nombre', 'categoria', 'precio', 'costo', 'stock', 'activo'],
  CLIENTES: ['cliente_id', 'nombre', 'telefono', 'email', 'tipo', 'fecha_registro', 'acepta_marketing'],
  VENTAS: ['fecha', 'pedido_id', 'cliente_id', 'sku', 'cantidad', 'total', 'canal', 'codigo'],
};
const TIPOS_CLIENTE = ['EMPRESA', 'PERSONA'];
const CANALES_VENTA = ['WEB', 'WHATSAPP', 'TIENDA'];

function syncTexto(v) { return v === undefined || v === null ? '' : String(v).trim(); }
function syncClave(v) { return syncTexto(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, '_'); }
function syncNumero(v) {
  const s = syncTexto(v).replace(/^S\/\s*/i, '').replace(/\s/g, '');
  if (!s) return null;
  // "1,234.50" o "1234,50": la coma es decimal solo si no hay punto.
  const limpio = s.includes('.') ? s.replace(/,/g, '') : s.replace(',', '.');
  const n = Number(limpio);
  return Number.isFinite(n) ? n : null;
}

// Fecha de la hoja -> YYYY-MM-DD. Acepta 2026-10-17, 17/10/2026, 17/10/26, ISO con hora y el número de serie de Sheets.
function fechaFuente(v) {
  const s = syncTexto(v);
  if (!s) return '';
  let g;
  if ((g = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/))) return armarFecha(+g[1], +g[2], +g[3]);
  if ((g = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2}|\d{4})$/))) return armarFecha(g[3].length === 2 ? 2000 + +g[3] : +g[3], +g[2], +g[1]);
  if (/^\d{5}(\.\d+)?$/.test(s)) return new Date(Date.UTC(1899, 11, 30) + Math.floor(Number(s)) * 864e5).toISOString().slice(0, 10);
  return '';
}
function armarFecha(y, m, d) {
  const t = new Date(Date.UTC(y, m - 1, d));
  return t.getUTCFullYear() === y && t.getUTCMonth() === m - 1 && t.getUTCDate() === d ? t.toISOString().slice(0, 10) : '';
}

function telefonoFuente(v) {
  const d = syncTexto(v).replace(/\D/g, '');
  if (/^9\d{8}$/.test(d)) return `51${d}`;
  return d.length >= 10 ? d : '';
}
function siNo(v, porDefecto) {
  const s = syncClave(v);
  if (!s) return porDefecto;
  return ['si', 'sí', 's', 'yes', 'y', 'true', '1', 'x'].includes(s) ? 'SI' : 'NO';
}

// URL de la carpeta (o el id suelto) -> folderId.
function extraerFolderId(url) {
  const s = syncTexto(url);
  let g;
  if ((g = s.match(/\/folders\/([A-Za-z0-9_-]{10,})/))) return g[1];
  if ((g = s.match(/[?&]id=([A-Za-z0-9_-]{10,})/))) return g[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(s)) return s;
  return '';
}

// Archivos de la carpeta (búsqueda de Drive) -> la hoja fuente: la que empieza por MERMIN_FUENTE o la primera Sheet.
function elegirHojaFuente(archivos) {
  const hojas = (archivos || []).filter(a => a && syncTexto(a.id) && (!a.mimeType || a.mimeType === MIME_SHEETS));
  const porNombre = hojas.find(a => syncTexto(a.name).toUpperCase().startsWith(PREFIJO_FUENTE));
  const elegida = porNombre || hojas[0];
  return elegida ? { id: syncTexto(elegida.id), nombre: syncTexto(elegida.name) } : null;
