// Filas leídas de una pestaña -> filas con claves normalizadas, sin filas vacías.
function filasLimpias(filas) {
  return (filas || [])
    .map(f => {
      const fila = {};
      for (const k of Object.keys(f || {})) if (k !== 'row_number') fila[syncClave(k)] = f[k];
